WITH customer_totals AS (SELECT customer_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, MAX(order_date) AS latest_order_date FROM orders WHERE order_date BETWEEN '2023-04-01' AND '2025-04-01' GROUP BY customer_id) SELECT c.id, c.city, c.age, ct.status_values, ct.latest_order_date FROM customers c LEFT JOIN customer_totals ct ON c.id = ct.customer_id ORDER BY 2 ASC
